CREATE OR REPLACE FUNCTION public.sentinel_execution_evidence_append(domain_value text, source_value text, key_value text, operation_value text, detail_value jsonb)
 RETURNS void
 LANGUAGE plpgsql
AS $function$DECLARE next_sequence bigint;
BEGIN
    IF pg_trigger_depth() < 1 THEN
        RAISE EXCEPTION 'execution evidence changes require a source trigger';
    END IF;
    UPDATE sentinel_execution_evidence_heads SET head_seq=head_seq+1,
        reset_generation=reset_generation + CASE WHEN operation_value='TRUNCATE' THEN 1 ELSE 0 END
        WHERE domain=domain_value RETURNING head_seq INTO next_sequence;
    IF NOT FOUND THEN RAISE EXCEPTION 'execution evidence head is absent'; END IF;
    INSERT INTO sentinel_execution_evidence_changes(domain,seq,source,evidence_key,operation,detail)
        VALUES(domain_value,next_sequence,source_value,key_value,operation_value,detail_value);
END$function$

CREATE OR REPLACE FUNCTION public.sentinel_execution_evidence_tracking_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$BEGIN
    IF TG_OP = 'TRUNCATE' OR pg_trigger_depth() < 2 OR TG_OP <> 'INSERT'
       AND TG_TABLE_NAME = 'sentinel_execution_evidence_changes' THEN
        RAISE EXCEPTION 'execution evidence tracking is producer-owned and append-only';
    END IF;
    RETURN NEW;
END$function$

CREATE OR REPLACE FUNCTION public.sentinel_execution_observation_changed()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$DECLARE before_value jsonb; after_value jsonb; evidence_key text;
BEGIN
    IF TG_OP='TRUNCATE' THEN
        PERFORM sentinel_execution_evidence_append('OBSERVATION',TG_TABLE_NAME,'*','TRUNCATE','{}'::jsonb);
        RETURN NULL;
    END IF;
    before_value=CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END;
    after_value=CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END;
    IF TG_TABLE_NAME='sentinel_observations' THEN
        IF TG_OP='UPDATE' AND before_value-'runtime_state'=after_value-'runtime_state' THEN RETURN NEW; END IF;
        evidence_key=COALESCE(before_value->>'seq',after_value->>'seq');
    ELSIF TG_TABLE_NAME='sentinel_observation_provenance' THEN
        evidence_key=COALESCE(before_value->>'observation_seq',after_value->>'observation_seq');
    ELSIF TG_TABLE_NAME='sentinel_processed_sessions' THEN
        IF COALESCE(before_value->>'cursor_name','') NOT LIKE 'broker-observation:v4:%'
           AND COALESCE(after_value->>'cursor_name','') NOT LIKE 'broker-observation:v4:%' THEN
            RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
        END IF;
        evidence_key=COALESCE(before_value->>'cursor_name',after_value->>'cursor_name');
    ELSE evidence_key='*binding*';
    END IF;
    IF TG_OP='UPDATE' AND before_value=after_value THEN RETURN NEW; END IF;
    PERFORM sentinel_execution_evidence_append('OBSERVATION',TG_TABLE_NAME,evidence_key,TG_OP,'{}'::jsonb);
    RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END$function$

CREATE OR REPLACE FUNCTION public.sentinel_normalized_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_TABLE_NAME='sentinel_normalized_blocks' AND TG_OP='UPDATE'
      AND (to_jsonb(NEW)-'canonical_payload')=(to_jsonb(OLD)-'canonical_payload') THEN
    IF OLD.canonical_payload IS NULL AND NEW.canonical_payload IS NOT NULL THEN RETURN NEW; END IF;
    IF NEW.canonical_payload IS NULL THEN
      PERFORM sentinel_retention_locks();
      IF NOT EXISTS(SELECT 1 FROM sentinel_candidate_blocks b WHERE b.block_sha256=OLD.block_sha256
          AND NOT EXISTS(SELECT 1 FROM sentinel_snapshot_retirements r WHERE r.candidate_id=b.candidate_id))
        THEN RETURN NEW; END IF;
    END IF;
  END IF;
  RAISE EXCEPTION 'normalized layout evidence is immutable';
END $function$

CREATE OR REPLACE FUNCTION public.sentinel_normalized_layout_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c RECORD; refs JSONB;
BEGIN
  SELECT snapshot_id,manifest INTO c FROM sentinel_price_candidates WHERE candidate_id=NEW.candidate_id FOR UPDATE;
  SELECT jsonb_agg(jsonb_build_object('kind',kind,'session',session::text,'block_sha256',block_sha256)
      ORDER BY kind,session) INTO refs FROM sentinel_candidate_blocks WHERE candidate_id=NEW.candidate_id;
  IF NOT FOUND OR c.manifest IS NULL OR c.snapshot_id<>NEW.snapshot_id
      OR refs IS NULL OR refs<>NEW.block_references OR NEW.layout->>'schema'<>'sentinel.normalized-snapshot-layout/1'
      OR NEW.layout->>'snapshot_id'<>NEW.snapshot_id OR NEW.layout->'references'<>refs
      OR NEW.layout->>'candidate_id'<>NEW.candidate_id::text THEN
    RAISE EXCEPTION 'normalized layout does not bind the sealed logical snapshot'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sentinel_normalized_reference_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c JSONB; b RECORD;
BEGIN
  SELECT manifest INTO c FROM sentinel_price_candidates WHERE candidate_id=NEW.candidate_id FOR UPDATE;
  IF NOT FOUND OR c IS NOT NULL THEN RAISE EXCEPTION 'normalized references require an owned unsealed candidate'; END IF;
  SELECT * INTO b FROM sentinel_normalized_blocks WHERE block_sha256=NEW.block_sha256 FOR SHARE;
  IF NOT FOUND OR b.canonical_payload IS NULL OR b.kind<>NEW.kind OR b.session<>NEW.session THEN
    RAISE EXCEPTION 'normalized reference does not bind a complete session payload'; END IF;
  IF EXISTS(SELECT 1 FROM sentinel_snapshot_bars WHERE candidate_id=NEW.candidate_id)
      OR EXISTS(SELECT 1 FROM sentinel_snapshot_benchmarks WHERE candidate_id=NEW.candidate_id) THEN
    RAISE EXCEPTION 'legacy and shared candidate payloads cannot mix'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.sentinel_paper_mirror_changed()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$DECLARE before_value jsonb; after_value jsonb; coordinates jsonb; plan_key text;
BEGIN
    IF TG_OP='TRUNCATE' THEN
        PERFORM sentinel_execution_evidence_append('MIRROR',TG_TABLE_NAME,'*','TRUNCATE','{}'::jsonb);
        RETURN NULL;
    END IF;
    before_value=CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END;
    after_value=CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END;
    IF TG_OP='UPDATE' AND before_value=after_value THEN RETURN NEW; END IF;
    IF TG_TABLE_NAME='sentinel_processed_sessions' THEN
        IF COALESCE(before_value->>'cursor_name','') NOT LIKE 'informational-paper-mirror:v1:%'
           AND COALESCE(after_value->>'cursor_name','') NOT LIKE 'informational-paper-mirror:v1:%' THEN
            RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
        END IF;
        plan_key=COALESCE(before_value->>'cursor_name',after_value->>'cursor_name');
        coordinates=jsonb_build_object('kind','legacy');
    ELSIF TG_TABLE_NAME='sentinel_paper_mirror_dependencies' THEN
        plan_key=COALESCE(before_value->>'plan_id',after_value->>'plan_id');
        coordinates=jsonb_build_object('kind','projection');
    ELSIF TG_TABLE_NAME='sentinel_execution_plans' THEN
        plan_key=COALESCE(before_value->>'plan_id',after_value->>'plan_id');
        IF TG_OP='UPDATE' AND before_value-'superseded_by'=after_value-'superseded_by' THEN RETURN NEW; END IF;
        IF NOT EXISTS(SELECT 1 FROM sentinel_paper_mirror_dependencies WHERE plan_id=plan_key) THEN
            RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
        END IF;
        coordinates=jsonb_build_object('kind','plan');
    ELSIF TG_TABLE_NAME='sentinel_corpus_publications' THEN
        plan_key=COALESCE(before_value->>'version',after_value->>'version');
        coordinates=jsonb_build_object('kind','publication','before',before_value,'after',after_value);
    ELSIF TG_TABLE_NAME='sentinel_action_history' THEN
        plan_key=COALESCE(before_value->>'session',after_value->>'session');
        coordinates=jsonb_build_object('kind','retained_history','session',plan_key);
    ELSIF TG_TABLE_NAME='sentinel_action_coverage' THEN
        plan_key=COALESCE(before_value->>'publication_version',after_value->>'publication_version');
        coordinates=jsonb_build_object('kind','retained_coverage','publication_version',plan_key);
    ELSIF TG_TABLE_NAME='feed_ingest_runs' THEN
        plan_key=COALESCE(before_value->>'run_id',after_value->>'run_id');
        IF NOT EXISTS(SELECT 1 FROM sentinel_corpus_publications WHERE run_id::text=plan_key)
           OR TG_OP='UPDATE' AND before_value->>'status'=after_value->>'status' THEN
            RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
        END IF;
        coordinates=jsonb_build_object('kind','unknown');
    ELSE
        IF TG_TABLE_NAME='sentinel_bars' AND TG_OP='UPDATE'
           AND before_value->'split_ratio'=after_value->'split_ratio'
           AND before_value->'security_id'=after_value->'security_id'
           AND before_value->'ticker'=after_value->'ticker'
           AND before_value->'session'=after_value->'session'
           AND before_value->'last_written_run_id'=after_value->'last_written_run_id' THEN RETURN NEW; END IF;
        coordinates=jsonb_build_object('kind','coordinate',
            'before',CASE WHEN before_value IS NULL THEN NULL ELSE jsonb_build_object(
                'security_id',before_value->>'security_id','ticker',before_value->>'ticker',
                'contraticker',before_value->>'contraticker','session',before_value->>'session',
                'run_id',before_value->>'last_written_run_id') END,
            'after',CASE WHEN after_value IS NULL THEN NULL ELSE jsonb_build_object(
                'security_id',after_value->>'security_id','ticker',after_value->>'ticker',
                'contraticker',after_value->>'contraticker','session',after_value->>'session',
                'run_id',after_value->>'last_written_run_id') END);
        plan_key='coordinate';
        IF NOT EXISTS(SELECT 1 FROM sentinel_paper_mirror_dependencies d WHERE
            (COALESCE(before_value->>'security_id','')=ANY(d.security_ids)
             OR COALESCE(after_value->>'security_id','')=ANY(d.security_ids)
             OR upper(COALESCE(before_value->>'ticker',''))=ANY(d.symbols)
             OR upper(COALESCE(after_value->>'ticker',''))=ANY(d.symbols)
             OR upper(COALESCE(before_value->>'contraticker',''))=ANY(d.symbols)
             OR upper(COALESCE(after_value->>'contraticker',''))=ANY(d.symbols))
            AND (((before_value->>'session')::date<=d.effective_session
                  AND (TG_TABLE_NAME='sentinel_defensive_bars' OR (before_value->>'session')::date>=d.raw_start))
                 OR ((after_value->>'session')::date<=d.effective_session
                  AND (TG_TABLE_NAME='sentinel_defensive_bars' OR (after_value->>'session')::date>=d.raw_start)))) THEN
            RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
        END IF;
    END IF;
    PERFORM sentinel_execution_evidence_append('MIRROR',TG_TABLE_NAME,plan_key,TG_OP,coordinates);
    RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END$function$

CREATE OR REPLACE FUNCTION public.sentinel_operational_ddl_epoch_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$BEGIN
    IF TG_OP<>'UPDATE' THEN
        RAISE EXCEPTION 'operational DDL epoch is audit-owned and cannot be reset';
    END IF;
    -- PostgreSQL refuses this call outside an event-trigger execution context.
    -- Nested row triggers retain that context; pg_trigger_depth alone would not
    -- distinguish a direct client UPDATE from an independently observed DDL.
    PERFORM 1 FROM pg_event_trigger_ddl_commands();
    IF NEW.id<>OLD.id OR NEW.incarnation<>OLD.incarnation OR NEW.epoch<>OLD.epoch+1 THEN
        RAISE EXCEPTION 'operational DDL epoch must advance exactly once';
    END IF;
    RETURN NEW;
END$function$

CREATE OR REPLACE FUNCTION public.sentinel_operational_installation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP='TRUNCATE' THEN
        RAISE EXCEPTION 'operational installation authority cannot be truncated';
    END IF;
    IF (TG_OP IN ('UPDATE','DELETE') AND OLD.cursor_name='operational-schema:v1')
       OR (TG_OP='UPDATE' AND NEW.cursor_name='operational-schema:v1') THEN
        RAISE EXCEPTION 'operational installation authority is immutable';
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.sentinel_operational_account_insert_bump()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE previous public.sentinel_broker_account_evidence%ROWTYPE;
BEGIN
    SELECT * INTO previous FROM public.sentinel_broker_account_evidence
        ORDER BY observed_at DESC,seq DESC LIMIT 1;
    IF FOUND AND NEW.observed_at>=previous.observed_at
       AND NEW.observed_at-previous.observed_at<=interval '10 minutes'
       AND (NEW.observed_at AT TIME ZONE 'America/New_York')::date
           =(previous.observed_at AT TIME ZONE 'America/New_York')::date
       AND (to_jsonb(NEW)-'seq'-'observed_at')
           IS NOT DISTINCT FROM (to_jsonb(previous)-'seq'-'observed_at') THEN
        RETURN NEW;
    END IF;
    UPDATE public.sentinel_operational_read_revisions SET revision=revision+1 WHERE scope='PAPER';
    IF NOT FOUND THEN RAISE EXCEPTION 'operational PAPER revision is missing'; END IF;
    RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.sentinel_operational_cursor_bump()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE shadow_changed boolean := false;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        shadow_changed := OLD.cursor_name <> ALL(ARRAY['broker-recovery-db-incarnation:v1']::text[])
            AND NOT (OLD.cursor_name LIKE ANY(ARRAY['broker-cash-activity:v1:%','broker-cash-plan:v1:%','broker-observation:v4:%','dual-regenesis-broker-handover:v2:%','informational-paper-mirror:v1:%','paper-performance-invalid:v1:%','plan-target-projection:v2:%','preopen-share-unit-authority:v1:%','protected-buy-funding:v1:%','terminal-recovery-witness:v3:%','trial-account:v2:%','trial-close-nav:v1:%','trial-fill-interval:v1:%','trial-verification:v3:%']::text[]));
    END IF;
    IF TG_OP <> 'DELETE' THEN
        shadow_changed := shadow_changed OR (NEW.cursor_name <> ALL(ARRAY['broker-recovery-db-incarnation:v1']::text[])
            AND NOT (NEW.cursor_name LIKE ANY(ARRAY['broker-cash-activity:v1:%','broker-cash-plan:v1:%','broker-observation:v4:%','dual-regenesis-broker-handover:v2:%','informational-paper-mirror:v1:%','paper-performance-invalid:v1:%','plan-target-projection:v2:%','preopen-share-unit-authority:v1:%','protected-buy-funding:v1:%','terminal-recovery-witness:v3:%','trial-account:v2:%','trial-close-nav:v1:%','trial-fill-interval:v1:%','trial-verification:v3:%']::text[])));
    END IF;
    UPDATE public.sentinel_operational_read_revisions SET revision=revision+1 WHERE scope='PAPER';
    IF NOT FOUND THEN RAISE EXCEPTION 'operational PAPER revision is missing'; END IF;
    IF shadow_changed THEN
        UPDATE public.sentinel_operational_read_revisions SET revision=revision+1 WHERE scope='SHADOW';
        IF NOT FOUND THEN RAISE EXCEPTION 'operational shadow revision is missing'; END IF;
    END IF;
    RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION public.sentinel_operational_projected_paper_bump()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE field text; changed boolean := false;
BEGIN
    IF TG_OP='UPDATE' THEN
        FOREACH field IN ARRAY string_to_array(TG_ARGV[0],',') LOOP
            IF (to_jsonb(OLD)->field) IS DISTINCT FROM (to_jsonb(NEW)->field) THEN
                changed := true;
                EXIT;
            END IF;
        END LOOP;
        IF NOT changed THEN RETURN NULL; END IF;
    END IF;
    UPDATE public.sentinel_operational_read_revisions SET revision=revision+1 WHERE scope='PAPER';
    IF NOT FOUND THEN RAISE EXCEPTION 'operational PAPER revision is missing'; END IF;
    RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION public.sentinel_operational_revision_bump()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    UPDATE public.sentinel_operational_read_revisions SET revision=revision+1
        WHERE scope='PAPER';
    IF NOT FOUND THEN RAISE EXCEPTION 'operational PAPER revision is missing'; END IF;
    IF TG_ARGV[0] = 'BOTH' THEN
        UPDATE public.sentinel_operational_read_revisions SET revision=revision+1
            WHERE scope='SHADOW';
    END IF;
    IF NOT FOUND THEN RAISE EXCEPTION 'operational revision state is missing'; END IF;
    RETURN NULL;
END
$function$
